 renderSchedulePreview(r){const box=document.getElementById('schedule-preview-box');box.classList.remove('hidden');box.innerHTML=`<div class="split"><b class="preview-ok">Xếp được ${r.plan.length}</b><b class="${r.unplaced.length?'preview-warn':'preview-ok'}">Chưa xếp ${r.unplaced.length}</b></div>`;r.plan.slice(0,80).forEach(x=>{const d=document.createElement('div');d.className='rule-chip';d.textContent=`${x.after.code} · ${this.matchLabel(x.after)} · ${x.after.date} ${x.after.time} · ${this.state.courts[x.after.courtId]?.name||''}`;box.appendChild(d)})},previewSchedule(){try{this.renderSchedulePreview(this.buildSchedulePlan())}catch(e){U.toast(e.message,'err')}},
 async autoSchedule(){try{const r=this.buildSchedulePlan();this.renderSchedulePreview(r);if(!r.plan.length)return U.toast('Không có lịch xếp được','info');if(!await U.confirmDanger('Áp dụng Smart Scheduler',`Cập nhật ${r.plan.length} lịch; ${r.unplaced.length} chưa xếp. Lịch ngoài khoảng/ngày khóa được giữ nguyên.`,'XẾP LỊCH'))return;const up={};r.plan.forEach(x=>up[T.Data.path('matches/'+x.after.id)]=x.after);await T.Data.queueMulti(up,{type:'SMART_SCHEDULE'});await T.Data.audit('SMART_SCHEDULE','schedule','bulk',null,{count:r.plan.length,unplaced:r.unplaced.length,input:r.input})}catch(e){U.toast(e.message,'err')}},
 async generateSchedule(){const teams=Object.values(this.state.teams||{}).filter(t=>!t.withdrawn),up={},existing=new Set(Object.values(this.state.matches||{}).map(m=>[m.teamAId,m.teamBId].filter(Boolean).sort().join('|')+'|'+m.category));let added=0;if(['time','judged'].includes(S.mode)){teams.forEach(t=>{if(Object.values(this.state.matches||{}).some(m=>m.teamAId===t.id))return;const id=U.id('match');up[T.Data.path('matches/'+id)]={id,code:(S.mode==='time'?'R':'M')+String(Object.keys(this.state.matches||{}).length+added+1).padStart(3,'0'),teamAId:t.id,teamBId:'',category:t.category||S.categories[0],stage:S.stages[0],date:'',time:'',courtId:'',status:'SCHEDULED',sets:[],createdAt:Date.now()};added++})}else for(let i=0;i<teams.length;i++)for(let j=i+1;j<teams.length;j++){if(teams[i].category!==teams[j].category)continue;const sig=[teams[i].id,teams[j].id].sort().join('|')+'|'+teams[i].category;if(existing.has(sig))continue;const id=U.id('match');up[T.Data.path('matches/'+id)]={id,code:'M'+String(Object.keys(this.state.matches||{}).length+added+1).padStart(3,'0'),teamAId:teams[i].id,teamBId:teams[j].id,category:teams[i].category,stage:'GROUP',date:'',time:'',courtId:'',status:'SCHEDULED',sets:[],createdAt:Date.now()};added++}if(!added)return U.toast('Không có lịch còn thiếu','info');await T.Data.queueMulti(up,{type:'GENERATE_SCHEDULE'});await T.Data.audit('GENERATE','schedule','bulk',null,{added})},
 openDelete(){document.getElementById('delete-from').value=document.getElementById('auto-date').value||this.localDate();document.getElementById('delete-to').value=document.getElementById('auto-end-date').value||this.localDate();document.getElementById('delete-protected').checked=false;document.querySelector('input[name="delete-scope"][value="range"]').checked=true;document.getElementById('schedule-delete-modal').classList.remove('hidden');this.previewDelete(false)},
 deletePlan(){const scope=document.querySelector('input[name="delete-scope"]:checked')?.value||'range',from=document.getElementById('delete-from').value,to=document.getElementById('delete-to').value,category=document.getElementById('delete-category').value,stage=document.getElementById('delete-stage').value,allow=document.getElementById('delete-protected').checked;if(scope==='range'&&(!from||!to||to<from))throw new Error('Khoảng ngày không hợp lệ');const active=new Set(Object.values(this.state.activeMatches||{}).filter(Boolean).map(x=>x.matchId)),isProtected=m=>active.has(m.id)||['LIVE','FINISHED','WALKOVER','RETIRED','DISQUALIFIED','SUSPENDED'].includes(m.status)||this.resultLabel(m)!=='—'||!!m.startedAt,candidates=Object.values(this.state.matches||{}).filter(m=>(category==='ALL'||m.category===category)&&(stage==='ALL'||m.stage===stage)&&(scope==='all'||(m.date>=from&&m.date<=to))),protectedMatches=candidates.filter(isProtected),deletable=candidates.filter(m=>allow||!isProtected(m));return{scope,from,to,category,stage,allow,candidates,protectedMatches,deletable,skipped:allow?[]:protectedMatches}},previewDelete(toast=true){try{const p=this.deletePlan();document.getElementById('delete-preview').innerHTML=`<b>Tìm thấy: ${p.candidates.length}</b><span class="delete-good">Sẽ xóa: ${p.deletable.length}</span><span class="delete-protect">Bảo vệ: ${p.skipped.length}</span>${p.allow&&p.protectedMatches.length?`<span class="delete-danger">⚠ Có ${p.protectedMatches.length} phiên đã bắt đầu/kết quả</span>`:''}`;if(toast)U.toast('Sẽ xóa '+p.deletable.length+' lịch','info');return p}catch(e){U.toast(e.message,'err');return null}},
 async executeDelete(){const p=this.previewDelete(false);if(!p?.deletable.length)return U.toast('Không có lịch phù hợp','info');const backup={type:'TOPKEY_SCHEDULE_DELETE_BACKUP',sport:S.key,version:T.VERSION,exportedAt:new Date().toISOString(),scope:p,matches:p.deletable};U.download(`Topkey_${S.key}_Backup_Lich_${this.localDate()}.json`,new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));const phrase=p.allow&&p.protectedMatches.length?'XÓA CẢ KẾT QUẢ':'XÓA LỊCH';if(!await U.confirmDanger('Xóa lịch an toàn',`Xóa ${p.deletable.length}; giữ ${p.skipped.length}. Backup JSON đã được tạo.`,phrase))return;const up={};p.deletable.forEach(m=>up[T.Data.path('matches/'+m.id)]=null);Object.entries(this.state.activeMatches||{}).forEach(([cid,a])=>{if(a&&p.deletable.some(m=>m.id===a.matchId)){up[T.Data.path('activeMatches/'+cid)]=null;const c=this.state.courts[cid];if(c)up[T.Data.path('courts/'+cid)]={...c,status:'AVAILABLE',activeMatchId:''}}});await T.Data.queueMulti(up,{type:'DELETE_SCHEDULE'});await T.Data.audit('DELETE_SCHEDULE','schedule','bulk',null,{ids:p.deletable.map(x=>x.id)});document.getElementById('schedule-delete-modal').classList.add('hidden')},
