function defaultsForRole(role){role=String(role||'VIEWER').toUpperCase();const modules={...ROLE_MODULES[role]||ROLE_MODULES.VIEWER},details={};Object.entries(MODULES).forEach(([m,def])=>Object.keys(def.details).forEach(d=>details[`${m}:${d}`]=modules[m]||'none'));return{modules,details};}
