 role=roleKey(role)||'VIEWER';const src=BUILTIN_MODULES[role]||BUILTIN_MODULES.VIEWER,modules={},details={};
 MODULE_KEYS.forEach(m=>{modules[m]=cleanLevel(src[m]||'none');(DETAILS[m]||[]).forEach(d=>details[`${m}:${d}`]=modules[m]);});
