const H89PURE2={"Firebase Auth dùng chung":{"vi":"Xác thực Firebase dùng chung","en":"Shared Firebase authentication","zh":"共用 Firebase 身份验证"},"Đội, check-in, lịch vòng tròn, Smart Scheduler, sân/trọng tài, chấm bàn thắng, BXH, Live, tài chính và audit.":{"vi":"Đội, điểm danh, lịch vòng tròn, xếp lịch thông minh, sân/trọng tài, chấm bàn thắng, bảng xếp hạng, trực tiếp, tài chính và nhật ký.","en":"Teams, check-in, round-robin schedule, smart scheduling, venues/referees, goal scoring, standings, live operations, finance and audit.","zh":"队伍、签到、循环赛程、智能排程、场地/裁判、进球记录、排名、直播、财务与审计。"},"Mở Football VNext →":{"vi":"Mở Bóng đá VNext →","en":"Open Football VNext →","zh":"打开足球 VNext →"},"Nguyên gói Badminton VNext mới nhất: multi-court, trọng tài, nhập tỷ số nhanh tại lịch, chính sách đội bỏ cuộc/BXH, Smart Scheduler theo khung giờ VĐV, lọc nhanh màn trọng tài, STT trận theo ngày, Live/BLV và finance.":{"vi":"Gói Cầu lông VNext mới nhất: nhiều sân, trọng tài, nhập tỷ số nhanh tại lịch, chính sách đội bỏ cuộc/bảng xếp hạng, xếp lịch thông minh theo khung giờ VĐV, lọc nhanh màn trọng tài, số thứ tự trận theo ngày, trực tiếp/BLV và tài chính.","en":"Latest Badminton VNext package: multi-court, officiating, quick score entry from schedule, withdrawal/standings policy, athlete-window smart scheduler, quick umpire filtering, daily match numbering, live/commentary and finance.","zh":"最新版羽毛球 VNext：多场地、裁判、赛程快速录入比分、退赛/排名规则、按运动员时段智能排程、裁判界面快速筛选、每日比赛编号、直播/解说与财务。"},"Mở Badminton VNext →":{"vi":"Mở Cầu lông VNext →","en":"Open Badminton VNext →","zh":"打开羽毛球 VNext →"},"Best-of-5, set 25 điểm và set quyết định 15 điểm, sân/trọng tài, lịch thông minh, BXH, Live và vận hành giải.":{"vi":"Thi đấu tối đa 5 hiệp, hiệp 25 điểm và hiệp quyết định 15 điểm, sân/trọng tài, lịch thông minh, bảng xếp hạng, trực tiếp và vận hành giải.","en":"Best-of-5, 25-point sets and a 15-point deciding set, venues/referees, smart schedule, standings, live operations and tournament management.","zh":"五局三胜制、每局 25 分且决胜局 15 分、场地/裁判、智能赛程、排名、直播与赛事运营。"},"Mở Volleyball VNext →":{"vi":"Mở Bóng chuyền VNext →","en":"Open Volleyball VNext →","zh":"打开排球 VNext →"},"VĐV, cự ly, lượt chạy, làn/khu, nhập thời gian, xếp hạng thành tích, Smart Scheduler, QR đăng ký và Live.":{"vi":"VĐV, cự ly, lượt chạy, làn/khu, nhập thời gian, xếp hạng thành tích, xếp lịch thông minh, mã QR đăng ký và trực tiếp.","en":"Athletes, distances, heats, lanes/areas, time entry, performance ranking, smart scheduling, registration QR and live operations.","zh":"运动员、距离、组次、跑道/区域、成绩录入、成绩排名、智能排程、报名二维码与直播。"},"Mở Running VNext →":{"vi":"Mở Chạy bộ VNext →","en":"Open Running VNext →","zh":"打开跑步 VNext →"},"Thí sinh/đội, khu trưng bày, lượt chấm, điểm giám khảo, xếp hạng, lịch, đăng ký QR, tài chính và audit.":{"vi":"Thí sinh/đội, khu trưng bày, lượt chấm, điểm giám khảo, xếp hạng, lịch, đăng ký mã QR, tài chính và nhật ký.","en":"Contestants/teams, display areas, judging rounds, judge scores, rankings, schedule, QR registration, finance and audit.","zh":"参赛者/队伍、展示区、评分轮次、评委评分、排名、赛程、二维码报名、财务与审计。"},"Mở Handmade VNext →":{"vi":"Mở Thủ công VNext →","en":"Open Handmade VNext →","zh":"打开手作 VNext →"},"Đơn/đôi/mix, chấm set rally point, sân/trọng tài, BXH, Smart Scheduler nhiều đội, Live/BLV và finance.":{"vi":"Đơn/đôi/hỗn hợp, chấm hiệp tính điểm trực tiếp, sân/trọng tài, bảng xếp hạng, xếp lịch thông minh nhiều đội, trực tiếp/BLV và tài chính.","en":"Singles/doubles/mixed, rally-point set scoring, venues/referees, standings, multi-team smart scheduling, live/commentary and finance.","zh":"单打/双打/混合、每球得分制、场地/裁判、排名、多队智能排程、直播/解说与财务。"},"Mở Shuttlecock VNext →":{"vi":"Mở Đá cầu VNext →","en":"Open Shuttlecock VNext →","zh":"打开毽球 VNext →"},"Đội thi, bếp/khu thi, lượt chấm, điểm giám khảo, lịch thông minh, QR đăng ký, Live, tài chính và audit.":{"vi":"Đội thi, bếp/khu thi, lượt chấm, điểm giám khảo, lịch thông minh, mã QR đăng ký, trực tiếp, tài chính và nhật ký.","en":"Teams, kitchens/competition areas, judging rounds, judge scores, smart schedule, QR registration, live operations, finance and audit.","zh":"参赛队、厨房/比赛区域、评分轮次、评委评分、智能赛程、二维码报名、直播、财务与审计。"},"Mở Cooking VNext →":{"vi":"Mở Nấu ăn VNext →","en":"Open Cooking VNext →","zh":"打开烹饪 VNext →"},"Nền tảng dùng chung · ADMIN":{"vi":"Nền tảng dùng chung · Quản trị viên","en":"Shared platform · Administrator","zh":"共用平台 · 管理员"},"Firebase Email/Password + role ADMIN / BTC / UMPIRE / VIEWER / LIVE_ONLY. Không dùng mật khẩu hard-code ở Hub.":{"vi":"Firebase dùng email/mật khẩu và các vai trò Quản trị viên / Ban tổ chức / Trọng tài / Người xem / Chỉ trực tiếp. Trung tâm không dùng mật khẩu ghi cứng.","en":"Firebase email/password with Administrator / Organizer / Umpire / Viewer / Live-only roles. The Hub uses no hard-coded passwords.","zh":"Firebase 使用邮箱/密码，并支持管理员 / 组委会 / 裁判 / 查看者 / 仅直播角色。体育中心不使用硬编码密码。"},"Preview phạm vi, bảo vệ phiên đã bắt đầu/kết quả và tự tạo JSON backup trước khi xóa hàng loạt.":{"vi":"Xem trước phạm vi, bảo vệ phiên đã bắt đầu/kết quả và tự tạo bản sao lưu JSON trước khi xóa hàng loạt.","en":"Preview scope, protect started sessions/results and automatically create a JSON backup before bulk deletion.","zh":"预览范围，保护已开始的场次/结果，并在批量删除前自动创建 JSON 备份。"},"IndexedDB write queue, sync lại khi Firebase kết nối trở lại và PWA app shell.":{"vi":"Hàng đợi ghi IndexedDB, đồng bộ lại khi Firebase kết nối trở lại và bộ khung ứng dụng PWA.","en":"IndexedDB write queue, resync when Firebase reconnects, and PWA app shell.","zh":"IndexedDB 写入队列，Firebase 恢复连接后重新同步，并使用 PWA 应用外壳。"},"Camera/HLS/Embed, bảng điểm Live, TOPKEY Local BLV, Mandarin/Pinyin, FX vỗ tay offline và AI Shuttle Replay. Camera/WebRTC giữ buffer replay local; EdgeOne Makers/DeepSeek Vision chỉ nhận vài frame nhỏ khi bật AI phân loại.":{"vi":"Camera/HLS/nhúng, bảng điểm trực tiếp, BLV cục bộ TOPKEY, tiếng Trung/Pinyin, hiệu ứng vỗ tay ngoại tuyến và phát lại cầu bằng AI. Camera/WebRTC giữ bộ đệm phát lại cục bộ; EdgeOne Makers/DeepSeek Vision chỉ nhận vài khung hình nhỏ khi bật phân loại AI.","en":"Camera/HLS/embed, live scoreboard, TOPKEY local commentary, Mandarin/Pinyin, offline applause effects and AI shuttle replay. Camera/WebRTC keeps the replay buffer locally; EdgeOne Makers/DeepSeek Vision receives only a few small frames when AI classification is enabled.","zh":"Camera/HLS/嵌入、实时记分牌、TOPKEY 本地解说、普通话/拼音、离线掌声特效与 AI 羽球回放。Camera/WebRTC 的回放缓冲保留在本机；仅在开启 AI 分类时向 EdgeOne Makers/DeepSeek Vision 发送少量小尺寸画面。"},"Thu/chi, chứng từ, ZIP export, announcement, audit log, backup/restore và System Health.":{"vi":"Thu/chi, chứng từ, xuất ZIP, thông báo, nhật ký kiểm tra, sao lưu/khôi phục và tình trạng hệ thống.","en":"Income/expense, receipts, ZIP export, announcements, audit log, backup/restore and system health.","zh":"收支、凭证、ZIP 导出、公告、审计日志、备份/恢复与系统状态。"},"Chọn môn và bấm một lần: hệ thống tự dựng toàn bộ dữ liệu giả theo cấu trúc production, chạy kiểm tra regression thực tế và lưu báo cáo ngay trong kênh test riêng. Không ghi vào":{"vi":"Chọn môn và bấm một lần: hệ thống tự dựng toàn bộ dữ liệu giả theo cấu trúc vận hành thật, chạy kiểm tra hồi quy thực tế và lưu báo cáo ngay trong kênh kiểm thử riêng. Không ghi vào","en":"Choose a sport and click once: the system builds a complete production-structured fixture, runs real regression checks and saves the report in a separate test channel. It does not write to","zh":"选择项目并点击一次：系统会按正式环境结构自动生成完整测试数据，执行真实回归检查，并将报告保存到独立测试通道。不会写入"},"Tự dựng: đăng ký · roster/check-in · lịch · kết quả · vòng bảng/vòng trong/final · LIVE · BXH · tài chính · thông báo · audit · scheduler + báo cáo test.":{"vi":"Tự dựng: đăng ký · danh sách/điểm danh · lịch · kết quả · vòng bảng/vòng trong/chung kết · trực tiếp · bảng xếp hạng · tài chính · thông báo · nhật ký · xếp lịch + báo cáo kiểm thử.","en":"Auto-build: registration · roster/check-in · schedule · results · group/knockout/final · live · standings · finance · announcements · audit · scheduler + test report.","zh":"自动生成：报名 · 名单/签到 · 赛程 · 结果 · 小组赛/淘汰赛/决赛 · 直播 · 排名 · 财务 · 公告 · 审计 · 排程 + 测试报告。"},"Tài khoản Firebase Auth · Backup/Restore · Database Firewall · Vai trò tùy chỉnh · Phân quyền chi tiết. Khi mở sẽ yêu cầu đăng nhập ADMIN hoặc tài khoản được cấp quyền quản trị.":{"vi":"Tài khoản xác thực Firebase · Sao lưu/Khôi phục · Tường lửa cơ sở dữ liệu · Vai trò tùy chỉnh · Phân quyền chi tiết. Khi mở sẽ yêu cầu đăng nhập quản trị viên hoặc tài khoản được cấp quyền quản trị.","en":"Firebase authentication accounts · Backup/Restore · Database Firewall · Custom roles · Detailed permissions. Opening this area requires an administrator or delegated system-administration access.","zh":"Firebase 身份验证账号 · 备份/恢复 · 数据库防火墙 · 自定义角色 · 详细权限。打开此区域需要管理员或已获系统管理权限的账号。"},"← Sports Hub":{"vi":"← Trung tâm thể thao","en":"← Sports Hub","zh":"← 体育中心"},"🔐 Tài khoản Firebase Auth dùng chung":{"vi":"🔐 Tài khoản xác thực Firebase dùng chung","en":"🔐 Shared Firebase authentication accounts","zh":"🔐 共用 Firebase 身份验证账号"},"🔒 Trang này là khu quản trị chung. Các môn chỉ giữ cấu hình nghiệp vụ của giải; quản lý tài khoản, backup, firewall và phân quyền được gom về đây.":{"vi":"🔒 Đây là khu quản trị chung. Các môn chỉ giữ cấu hình nghiệp vụ của giải; quản lý tài khoản, sao lưu, tường lửa và phân quyền được gom về đây.","en":"🔒 This is the shared administration area. Sport pages keep tournament-specific settings only; accounts, backup, firewall and permissions are managed here.","zh":"🔒 这是统一系统管理区。各项目页面仅保留赛事业务设置；账号、备份、防火墙和权限统一在此管理。"},"ADMIN có thể bấm":{"vi":"Quản trị viên có thể bấm","en":"The administrator can press","zh":"管理员可以点击"},". ADMIN có thể bấm":{"vi":". Quản trị viên có thể bấm","en":". The administrator can press","zh":"。管理员可以点击"},"Khi chọn tài khoản, hệ thống nạp đồng thời thông tin tài khoản + môn phụ trách + toàn bộ quyền chi tiết bên dưới. Form này không tự lấy tài khoản ADMIN đang đăng nhập.":{"vi":"Khi chọn tài khoản, hệ thống nạp đồng thời thông tin tài khoản + môn phụ trách + toàn bộ quyền chi tiết bên dưới. Biểu mẫu này không tự lấy tài khoản quản trị viên đang đăng nhập.","en":"Selecting an account loads its profile, assigned sport and all detailed permissions below. This form never auto-selects the administrator currently signed in.","zh":"选择账号后，系统会同时载入账号资料、负责项目及下方全部详细权限。此表单不会自动选中当前登录的管理员账号。"},"Quản trị chung: users / roles / security / indexes / dashboard":{"vi":"Quản trị chung: người dùng / vai trò / bảo mật / chỉ mục / bảng điều khiển","en":"Shared administration: users / roles / security / indexes / dashboard","zh":"统一管理：用户 / 角色 / 安全 / 索引 / 仪表板"},"Tournament ID (để trống = toàn root môn)":{"vi":"Mã giải (để trống = toàn bộ gốc dữ liệu của môn)","en":"Tournament ID (blank = entire sport root)","zh":"赛事 ID（留空 = 整个项目根节点）"},"⬆ Restore JSON":{"vi":"⬆ Khôi phục JSON","en":"⬆ Restore JSON","zh":"⬆ 恢复 JSON"},"Export không thay đổi dữ liệu. Restore chỉ mở cho quyền":{"vi":"Xuất dữ liệu không làm thay đổi dữ liệu. Khôi phục chỉ mở cho quyền","en":"Export does not change data. Restore is available only to permission","zh":"导出不会修改数据。恢复仅向以下权限开放："},"🛡️ TƯỜNG LỬA DATABASE & CHỐNG SAO CHÉP":{"vi":"🛡️ TƯỜNG LỬA CƠ SỞ DỮ LIỆU & CHỐNG SAO CHÉP","en":"🛡️ DATABASE FIREWALL & COPY PROTECTION","zh":"🛡️ 数据库防火墙与防复制"},"Bật firewall UI":{"vi":"Bật tường lửa giao diện","en":"Enable interface firewall","zh":"启用界面防火墙"},"Mật khẩu firewall mới (để trống nếu giữ nguyên)":{"vi":"Mật khẩu tường lửa mới (để trống nếu giữ nguyên)","en":"New firewall password (blank to keep current)","zh":"新防火墙密码（留空则保持不变）"},"Tải Firebase Rules":{"vi":"Tải quy tắc Firebase","en":"Download Firebase Rules","zh":"下载 Firebase 规则"},"Chọn môn/Tournament ID rồi nạp.":{"vi":"Chọn môn/Mã giải rồi nạp.","en":"Choose sport/Tournament ID, then load.","zh":"选择项目/赛事 ID 后载入。"},"Mã role":{"vi":"Mã vai trò","en":"Role code","zh":"角色代码"},"＋ Tạo / ghi đè role":{"vi":"＋ Tạo / ghi đè vai trò","en":"＋ Create / overwrite role","zh":"＋ 创建 / 覆盖角色"},"-- Chọn role --":{"vi":"-- Chọn vai trò --","en":"-- Choose role --","zh":"-- 选择角色 --"},"💾 Lưu quyền role":{"vi":"💾 Lưu quyền vai trò","en":"💾 Save role permissions","zh":"💾 保存角色权限"},"Áp dụng cho tài khoản dùng role":{"vi":"Áp dụng cho tài khoản dùng vai trò","en":"Apply to accounts using role","zh":"应用到使用该角色的账号"},"Xóa role":{"vi":"Xóa vai trò","en":"Delete role","zh":"删除角色"},"Quản lý tập trung tên xã đoàn, tên CLB, năm thành lập, Trưởng BTC/phụ trách và trạng thái hoạt động. Mục này đã được chuyển khỏi Sports Hub.":{"vi":"Quản lý tập trung tên xã đoàn, tên CLB, năm thành lập, Trưởng Ban tổ chức/phụ trách và trạng thái hoạt động. Mục này đã được chuyển khỏi Trung tâm thể thao.","en":"Centrally manage organization name, club name, founding year, organizer/person in charge and activity status. This section was moved out of the Sports Hub.","zh":"集中管理社团名称、俱乐部名称、成立年份、组委会负责人/主管以及活动状态。此功能已从体育中心移至此处。"},"Editor chung dùng cho tài khoản đang chọn hoặc vai trò tùy chỉnh.":{"vi":"Trình chỉnh sửa chung dùng cho tài khoản đang chọn hoặc vai trò tùy chỉnh.","en":"Shared editor for the selected account or custom role.","zh":"统一编辑器用于当前所选账号或自定义角色。"},"← Về Sports Hub":{"vi":"← Về Trung tâm thể thao","en":"← Back to Sports Hub","zh":"← 返回体育中心"},"Live & BLV":{"vi":"Trực tiếp & BLV","en":"Live & Commentary","zh":"直播与解说"},"Live":{"vi":"Trực tiếp","en":"Live","zh":"直播"},"Check-in":{"vi":"Điểm danh","en":"Check-in","zh":"签到"},"Finance & Audit":{"vi":"Tài chính & Nhật ký","en":"Finance & Audit","zh":"财务与审计"},"Migration & Backup":{"vi":"Di chuyển dữ liệu & Sao lưu","en":"Migration & Backup","zh":"数据迁移与备份"},"Live Viewer":{"vi":"Trình xem trực tiếp","en":"Live Viewer","zh":"直播查看器"},"Reset set":{"vi":"Đặt lại hiệp","en":"Reset set","zh":"重置本局"},"Preset":{"vi":"Cấu hình sẵn","en":"Preset","zh":"预设"}};
