function translateString(source,lang){const lead=(source.match(/^\s*/)||[''])[0],trail=(source.match(/\s*$/)||[''])[0],s=source.trim();if(!s)return source;let exact=D[s]?.[lang];if(!exact){const low=s.toLocaleLowerCase('vi');const k=Object.keys(D).find(x=>x.toLocaleLowerCase('vi')===low);if(k)exact=D[k]?.[lang];}const pat=patternTranslate(s,lang);return lead+(exact||pat||s)+trail;}
