function translateTextNode(node){if(shouldSkip(node))return;let st=textState.get(node),now=node.nodeValue||'';if(!st){st={source:now,last:null};textState.set(node,st);}else if(st.last!==null&&now!==st.last){st.source=now;}if(isProtectedExact(st.source)&&node.parentElement?.closest?.(USER_VALUE_ZONE)){st.last=now;return;}const out=translateString(st.source,current);if(now!==out){node.nodeValue=out;}st.last=out;}
function translateAttrs(el){if(!(el instanceof Element)||el.closest('[data-tk28-no-translate]'))return;let st=attrState.get(el);if(!st){st={};attrState.set(el,st);}const attrs=['placeholder','title','aria-label','alt'];if(el.tagName==='INPUT'&&['button','submit','reset'].includes(String(el.type||'').toLowerCase()))attrs.push('value');for(const a of attrs){if(!el.hasAttribute(a))continue;const now=el.getAttribute(a)||'';const prev=st[a];if(!prev)st[a]={source:now,last:null};else if(prev.last!==null&&now!==prev.last)prev.source=now;const rec=st[a];const s=rec.source.trim(),special=PLACEHOLDER[s]?.[current];const out=special||translateString(rec.source,current);if(now!==out)el.setAttribute(a,out);rec.last=out;}}
function walk(root=document.body){if(!root)return;refreshProtectedValues();applying=true;try{if(root.nodeType===Node.TEXT_NODE)translateTextNode(root);else{if(root.nodeType===Node.ELEMENT_NODE)translateAttrs(root);const w=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){if(n.nodeType===Node.TEXT_NODE)translateTextNode(n);else translateAttrs(n);}}}finally{applying=false;}}
