 const champions=Object.entries(r.top4||{}).map(([cat,rows])=>`<div class="champ"><b>${esc(cat)}</b>${rows.map(x=>`<div>${x.rank}. ${esc(x.name)}${x.rank===1?' 🥇':''}</div>`).join('')}</div>`).join('');
 const results=(r.matches||[]).map((m,i)=>`<tr><td>${i+1}</td><td>${esc(m.date)} ${esc(m.time)}</td><td>${esc(m.category)}</td><td>${esc(m.stage)}</td><td>${esc(m.teamA)}${m.teamB&&m.teamB!=='—'?' vs '+esc(m.teamB):''}</td><td>${esc(m.result)}</td><td>${esc(m.status)}</td></tr>`).join('');
 const frows=(r.finance?.rows||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.date)}</td><td>${esc(x.type)}</td><td>${esc(x.category)}</td><td>${money(x.amount)}</td><td>${esc(x.status)}</td><td>${esc(x.note)}</td></tr>`).join('');
