 return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${esc(reportFileBase(r))} [H107]</title><meta name="topkey-report-build" content="H107"><style>body{font-family:Arial,"Segoe UI",sans-serif;color:#10233b;margin:30px;background:#fff}.wrap{max-width:1150px;margin:auto}header{border-bottom:3px solid #0f789d;padding-bottom:16px}h1{margin:0 0 6px}h2{margin-top:26px;color:#105d7e}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.kpi,.champ{border:1px solid #bdd3df;border-radius:10px;padding:12px}.kpi b{font-size:22px;display:block}.champions{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #c6d6df;padding:6px;text-align:left}th{background:#eaf5fa}.top{background:#fff8d6}.note{color:#547083}.sign{text-align:center;margin:45px 0 10px;margin-left:auto;width:380px}.space{height:70px}@media(max-width:800px){.kpis{grid-template-columns:1fr 1fr}body{margin:12px}.tablewrap{overflow:auto}}</style></head><body><div class="wrap"><header><h1>📊 BÁO CÁO TOÀN GIẢI</h1><h2>${esc(r.title)}</h2><div>${esc(r.sportName)} · Tournament ID: <b>${esc(r.tid)}</b></div><div class="note">Tự động chốt khi toàn bộ trận/lượt của giải đã kết thúc · ${fmtDate(r.generatedAt)}</div></header><div class="kpis"><div class="kpi">Đội/đối tượng<b>${r.summary?.teams||0}</b></div><div class="kpi">VĐV/người tham gia<b>${r.summary?.participants||0}</b></div><div class="kpi">Trận/lượt hoàn tất<b>${r.summary?.finished||0}/${r.summary?.matches||0}</b></div><div class="kpi">Nội dung<b>${r.summary?.categories||0}</b></div></div><section><h2>🥇 Thành tích chung cuộc</h2><div class="champions">${champions||'<p>Chưa có BXH.</p>'}</div></section>${h107AwardSection(r)}${ranks}<section><h2>📅 Toàn bộ lịch & kết quả</h2><div class="tablewrap"><table><thead><tr><th>#</th><th>Thời gian</th><th>Nội dung</th><th>Vòng</th><th>Trận/Lượt</th><th>Kết quả</th><th>Trạng thái</th></tr></thead><tbody>${results}</tbody></table></div></section><section><h2>💰 Tài chính toàn giải</h2><div class="kpis"><div class="kpi">Tổng thu<b>${money(r.finance?.income)}</b></div><div class="kpi">Tổng chi<b>${money(r.finance?.expense)}</b></div><div class="kpi">Số dư<b>${money(r.finance?.balance)}</b></div><div class="kpi">Khoản chưa PAID<b>${r.finance?.pending||0}</b></div></div><div class="tablewrap"><table><thead><tr><th>#</th><th>Ngày</th><th>Loại</th><th>Hạng mục</th><th>Số tiền</th><th>Trạng thái</th><th>Ghi chú</th></tr></thead><tbody>${frows||'<tr><td colspan="7">Chưa có dữ liệu tài chính.</td></tr>'}</tbody></table></div></section><div class="sign"><b>BTC - ${esc(r.title)}</b><div>Ngày ${d.getDate()} tháng ${d.getMonth()+1} năm ${d.getFullYear()}</div><div class="space"></div><div>(Ký, ghi rõ họ tên)</div></div><footer class="note"><b>TOPKEY REPORT H116</b> - Báo cáo được sinh tự động từ dữ liệu giải tại thời điểm toàn bộ lịch đã hoàn tất. Nếu dữ liệu tài chính được cập nhật trước khi đóng giải, snapshot báo cáo sẽ tự làm mới.</footer></div></body></html>`;
