function installCurrentUi(){const card=document.getElementById('tk9-lifecycle-card');if(!card||document.getElementById('tk65-final-report'))return;const d=document.createElement('div');d.id='tk65-final-report';d.style.cssText='margin-top:12px;padding:10px;border:1px solid #245e7b;border-radius:10px;background:#0a2034';d.innerHTML='<div id="tk65-final-report-status" class="tk9-small">Báo cáo toàn giải sẽ tự tạo khi toàn bộ lịch kết thúc.</div><div class="tk9-actions" style="margin-top:8px"><button id="tk65-download-current" class="btn ok" style="display:none">⬇ Tải Báo cáo toàn giải</button><button id="tk65-refresh-current" class="btn" style="display:none">↻ Cập nhật báo cáo</button></div>';const status=document.getElementById('tk9-lifecycle-status');status?.insertAdjacentElement('afterend',d);document.getElementById('tk65-download-current').onclick=()=>downloadReport(currentReport||buildReport());document.getElementById('tk65-refresh-current').onclick=()=>ensureReport(true)}
