function reportFileBase(r){return `${ddmmyyyy(r.generatedAt)}_Báo cáo toàn giải_${safe(r.sportName)}_${safe(r.title)}_${safe(r.tid)}`}
function ensureCss(){if($('tk76-style'))return;const s=document.createElement('style');s.id='tk76-style';s.textContent=`
#tk76-modal{position:fixed;inset:0;z-index:999999;background:rgba(2,10,20,.78);display:flex;align-items:center;justify-content:center;padding:18px}#tk76-modal.tk76-hidden{display:none}.tk76-box{width:min(1100px,96vw);max-height:92vh;overflow:auto;background:#0b2034;color:#eaf6ff;border:1px solid #2c6b8f;border-radius:16px;box-shadow:0 24px 90px #0008;padding:18px}.tk76-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.tk76-head h2{margin:0}.tk76-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:14px;margin-top:14px}.tk76-panel{border:1px solid #234b68;border-radius:12px;padding:12px;background:#0d2942}.tk76-panel h3{margin:0 0 10px}.tk76-upload{border:1px dashed #3b8ab2;border-radius:12px;padding:14px;text-align:center}.tk76-upload input{width:100%;margin-top:8px}.tk76-images{display:grid;gap:10px;margin-top:12px}.tk76-row{display:grid;grid-template-columns:120px 1fr auto;gap:10px;align-items:center;border:1px solid #274b65;border-radius:10px;padding:8px;background:#0a1b2c}.tk76-row img{width:120px;height:82px;object-fit:cover;border-radius:8px;background:#fff}.tk76-fields{display:grid;grid-template-columns:1fr;gap:7px}.tk76-fields select,.tk76-fields input[type=text],#tk76-final-title{width:100%;box-sizing:border-box;padding:8px;border-radius:8px;border:1px solid #3a607a;background:#061827;color:#fff}.tk76-title-line{display:flex;gap:8px;align-items:center}.tk76-title-line input[type=text]{flex:1}.tk76-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.tk76-actions button{padding:10px 14px;border:0;border-radius:9px;cursor:pointer;font-weight:700}.tk76-primary{background:#16a7e0;color:#03131f}.tk76-ok{background:#1fc98b;color:#031b13}.tk76-alt{background:#334e67;color:#fff}.tk76-danger{background:#6a3040;color:#fff}.tk76-note{font-size:12px;color:#a9c1d2;line-height:1.45}.tk76-empty{padding:18px;text-align:center;color:#8faabd;border:1px dashed #315873;border-radius:10px}.tk76-status{min-height:20px;margin-top:8px;color:#8fe7c0;font-size:13px}@media(max-width:820px){.tk76-grid{grid-template-columns:1fr}.tk76-row{grid-template-columns:88px 1fr}.tk76-row img{width:88px;height:70px}.tk76-row>button{grid-column:1/-1}}
`;document.head.appendChild(s)}
function cleanup(){reportRef=null;images=[];const box=$('tk76-images');if(box)box.innerHTML='';const input=$('tk76-files');if(input)input.value='';const st=$('tk76-status');if(st)st.textContent=''}
function closeModal(){const m=$('tk76-modal');if(m)m.classList.add('tk76-hidden');cleanup()}
function ensureModal(){ensureCss();if($('tk76-modal'))return;const m=document.createElement('div');m.id='tk76-modal';m.className='tk76-hidden';m.innerHTML=`<div class="tk76-box"><div class="tk76-head"><div><h2>📊 Xuất Báo cáo toàn giải</h2><div class="tk76-note">Có thể chèn ảnh vào từng mục hoặc gom thành một mục hình ảnh cuối báo cáo. Ảnh chỉ dùng trong lần xuất này và không lưu lên Firebase/Database.</div></div><button id="tk76-close" class="btn mini">✕ Đóng</button></div><div class="tk76-grid"><div class="tk76-panel"><h3>🖼️ Chèn hình ảnh</h3><div class="tk76-upload"><b>Thêm hình ảnh vào báo cáo</b><br><span class="tk76-note">Chọn nhiều ảnh JPG/PNG/WebP. Ảnh lớn sẽ được thu nhỏ trong bộ nhớ trình duyệt.</span><input id="tk76-files" type="file" accept="image/jpeg,image/png,image/webp" multiple></div><div id="tk76-images" class="tk76-images"><div class="tk76-empty">Chưa thêm hình ảnh.</div></div></div><div class="tk76-panel"><h3>⚙️ Thiết lập xuất</h3><label class="tk76-note">Tiêu đề mục hình ảnh cuối báo cáo</label><input id="tk76-final-title" type="text" value="HÌNH ẢNH HOẠT ĐỘNG GIẢI"><p class="tk76-note">Với mỗi ảnh: chọn vị trí chèn. Tick <b>Có tiêu đề ảnh</b> nếu muốn nhập chú thích; bỏ tick thì ảnh xuất ra không có tiêu đề.</p><div class="tk76-actions"><button id="tk76-pdf" class="tk76-primary">📄 Xuất PDF</button><button id="tk76-ppt" class="tk76-ok">📊 Xuất PowerPoint (.pptx)</button><button id="tk76-preview" class="tk76-alt">👁 Xem trước</button><button id="tk76-clear" class="tk76-danger">Xóa ảnh đã thêm</button></div><div id="tk76-status" class="tk76-status"></div></div></div></div>`;document.body.appendChild(m);$('tk76-close').onclick=closeModal;$('tk76-files').onchange=e=>addFiles([...e.target.files||[]]);$('tk76-clear').onclick=()=>{images=[];renderImages();$('tk76-files').value=''};$('tk76-preview').onclick=preview;$('tk76-pdf').onclick=exportPdf;$('tk76-ppt').onclick=exportPpt}
async function resizeFile(file){if(file.size>15*1024*1024)throw new Error(`${file.name}: ảnh vượt quá 15 MB`);const raw=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=()=>rej(fr.error);fr.readAsDataURL(file)});return await new Promise((res)=>{const im=new Image();im.onload=()=>{const maxW=1800,maxH=1300,scale=Math.min(1,maxW/im.width,maxH/im.height);if(scale===1&&file.size<2.5*1024*1024)return res(raw);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.86))};im.onerror=()=>res(raw);im.src=raw})}
async function addFiles(files){if(!files.length)return;const st=$('tk76-status');st.textContent='Đang xử lý ảnh...';for(const f of files.slice(0,30)){try{const data=await resizeFile(f);images.push({id:'img_'+Date.now().toString(36)+Math.random().toString(36).slice(2),name:f.name,data,position:'final',hasTitle:false,title:''})}catch(e){U.toast(e.message||String(e),'err')}}renderImages();st.textContent=`Đã thêm ${images.length} ảnh. Ảnh chưa được lưu vào hệ thống.`;$('tk76-files').value=''}
function renderImages(){const box=$('tk76-images');if(!box)return;if(!images.length){box.innerHTML='<div class="tk76-empty">Chưa thêm hình ảnh.</div>';return}box.innerHTML=images.map((x,i)=>`<div class="tk76-row" data-id="${x.id}"><img src="${x.data}" alt=""><div class="tk76-fields"><b>${i+1}. ${esc(x.name)}</b><select class="tk76-pos">${positions.map(p=>`<option value="${p[0]}" ${x.position===p[0]?'selected':''}>${p[1]}</option>`).join('')}</select><div class="tk76-title-line"><label><input class="tk76-hastitle" type="checkbox" ${x.hasTitle?'checked':''}> Có tiêu đề ảnh</label><input class="tk76-title" type="text" placeholder="Nhập tiêu đề / chú thích ảnh" value="${esc(x.title)}" ${x.hasTitle?'':'disabled'}></div></div><button class="btn mini tk76-remove">Xóa</button></div>`).join('');box.querySelectorAll('.tk76-row').forEach(row=>{const x=images.find(v=>v.id===row.dataset.id);row.querySelector('.tk76-pos').onchange=e=>x.position=e.target.value;row.querySelector('.tk76-hastitle').onchange=e=>{x.hasTitle=e.target.checked;row.querySelector('.tk76-title').disabled=!x.hasTitle;if(!x.hasTitle)x.title=''};row.querySelector('.tk76-title').oninput=e=>x.title=e.target.value;row.querySelector('.tk76-remove').onclick=()=>{images=images.filter(v=>v.id!==x.id);renderImages()}})}
function openExport(report){if(window.TopkeyUpgrade122Hotfix79)return window.TopkeyUpgrade122Hotfix79.openExport(report);ensureModal();const next=report||H65.buildReport();const same=!!(reportRef&&next&&String(reportRef.tid||'')===String(next.tid||''));reportRef=next;if(!same)images=[];renderImages();if(!$('tk76-final-title').value)$('tk76-final-title').value='HÌNH ẢNH HOẠT ĐỘNG GIẢI';$('tk76-status').textContent=images.length?`Đang giữ ${images.length} ảnh tạm cho báo cáo này.`:'';$('tk76-modal').classList.remove('tk76-hidden')}
function imgHtml(pos,final=false,source=images){const rows=(source||[]).filter(x=>x.position===pos);if(!rows.length)return'';const title=final?`<h2>📷 ${esc($('tk76-final-title')?.value||'HÌNH ẢNH HOẠT ĐỘNG GIẢI')}</h2>`:'';return `<section class="photo-section">${title}<div class="photo-grid">${rows.map(x=>`<figure><img src="${x.data}">${x.hasTitle&&x.title.trim()?`<figcaption>${esc(x.title.trim())}</figcaption>`:''}</figure>`).join('')}</div></section>`}
function reportHtml(r,source=images){const ranks=Object.entries(r.rankings||{}).map(([cat,rows])=>`<section><h2>🏆 Bảng xếp hạng · ${esc(cat)}</h2><table><thead><tr><th>#</th><th>Đội / VĐV</th><th>Trận/Lượt</th><th>W-D-L</th><th>HS</th><th>Điểm/Thành tích</th></tr></thead><tbody>${rows.map(x=>`<tr class="${x.rank<=4?'top':''}"><td>${x.rank}</td><td>${esc(x.name)}</td><td>${x.played??0}</td><td>${S.mode==='time'||S.mode==='judged'?'—':`${x.w||0}-${x.d||0}-${x.l||0}`}</td><td>${S.mode==='time'||S.mode==='judged'?'—':(Number(x.for||0)-Number(x.against||0))}</td><td>${esc(rankingValue(x))}</td></tr>`).join('')}</tbody></table></section>`).join('');const champions=Object.entries(r.top4||{}).map(([cat,rows])=>`<div class="champ"><b>${esc(cat)}</b>${rows.map(x=>`<div>${x.rank}. ${esc(x.name)}${x.rank===1?' 🥇':''}</div>`).join('')}</div>`).join('');const results=(r.matches||[]).map((m,i)=>`<tr><td>${i+1}</td><td>${esc(m.date)} ${esc(m.time)}</td><td>${esc(m.category)}</td><td>${esc(m.stage)}</td><td>${esc(m.teamA)}${m.teamB&&m.teamB!=='—'?' vs '+esc(m.teamB):''}</td><td>${esc(m.result)}</td><td>${esc(m.status)}</td></tr>`).join('');const frows=(r.finance?.rows||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.date)}</td><td>${esc(x.type)}</td><td>${esc(x.category)}</td><td>${money(x.amount)}</td><td>${esc(x.status)}</td><td>${esc(x.note)}</td></tr>`).join('');const d=new Date(r.generatedAt||Date.now());return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${esc(reportFileBase(r))}</title><style>@page{size:A4;margin:12mm}body{font-family:Arial,"Segoe UI",sans-serif;color:#10233b;margin:0;background:#fff}.wrap{max-width:1150px;margin:auto}header{border-bottom:3px solid #0f789d;padding-bottom:16px}h1{margin:0 0 6px}h2{margin-top:24px;color:#105d7e;break-after:avoid}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.kpi,.champ{border:1px solid #bdd3df;border-radius:10px;padding:12px}.kpi b{font-size:22px;display:block}.champions{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}table{width:100%;border-collapse:collapse;font-size:10.5px}th,td{border:1px solid #c6d6df;padding:5px;text-align:left}th{background:#eaf5fa}.top{background:#fff8d6}.note{color:#547083}.sign{text-align:center;margin:38px 0 10px;margin-left:auto;width:340px}.space{height:58px}.photo-section{break-inside:avoid;margin:18px 0}.photo-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.photo-grid figure{margin:0;border:1px solid #c8d9e2;border-radius:10px;padding:8px;break-inside:avoid}.photo-grid img{width:100%;max-height:330px;object-fit:contain;display:block}.photo-grid figcaption{text-align:center;font-weight:700;margin-top:7px;font-size:12px}@media print{.photo-grid figure{page-break-inside:avoid}}@media(max-width:800px){.kpis,.champions,.photo-grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><header><h1>📊 BÁO CÁO TOÀN GIẢI</h1><h2>${esc(r.title)}</h2><div>${esc(r.sportName)} · Tournament ID: <b>${esc(r.tid)}</b></div><div class="note">Tự động chốt khi toàn bộ trận/lượt của giải đã kết thúc · ${fmtDate(r.generatedAt)}</div></header><div class="kpis"><div class="kpi">Đội/đối tượng<b>${r.summary?.teams||0}</b></div><div class="kpi">VĐV/người tham gia<b>${r.summary?.participants||0}</b></div><div class="kpi">Trận/lượt hoàn tất<b>${r.summary?.finished||0}/${r.summary?.matches||0}</b></div><div class="kpi">Nội dung<b>${r.summary?.categories||0}</b></div></div>${imgHtml('summary',false,source)}<section><h2>🥇 Thành tích chung cuộc</h2><div class="champions">${champions||'<p>Chưa có BXH.</p>'}</div></section>${imgHtml('champions',false,source)}${ranks}${imgHtml('rankings',false,source)}<section><h2>📅 Toàn bộ lịch & kết quả</h2><table><thead><tr><th>#</th><th>Thời gian</th><th>Nội dung</th><th>Vòng</th><th>Trận/Lượt</th><th>Kết quả</th><th>Trạng thái</th></tr></thead><tbody>${results}</tbody></table></section>${imgHtml('results',false,source)}<section><h2>💰 Tài chính toàn giải</h2><div class="kpis"><div class="kpi">Tổng thu<b>${money(r.finance?.income)}</b></div><div class="kpi">Tổng chi<b>${money(r.finance?.expense)}</b></div><div class="kpi">Số dư<b>${money(r.finance?.balance)}</b></div><div class="kpi">Khoản chưa PAID<b>${r.finance?.pending||0}</b></div></div><table><thead><tr><th>#</th><th>Ngày</th><th>Loại</th><th>Hạng mục</th><th>Số tiền</th><th>Trạng thái</th><th>Ghi chú</th></tr></thead><tbody>${frows||'<tr><td colspan="7">Chưa có dữ liệu tài chính.</td></tr>'}</tbody></table></section>${imgHtml('finance',false,source)}${imgHtml('final',true,source)}<div class="sign"><b>BTC - ${esc(r.title)}</b><div>Ngày ${d.getDate()} tháng ${d.getMonth()+1} năm ${d.getFullYear()}</div><div class="space"></div><div>(Ký, ghi rõ họ tên)</div></div><footer class="note">Báo cáo được sinh tự động từ dữ liệu giải. Hình ảnh đính kèm chỉ tồn tại trong lần xuất báo cáo này và không được lưu vào hệ thống.</footer></div></body></html>`}
function preview(){if(!reportRef)return;const snap=images.map(x=>({...x}));const w=window.open('','_blank');if(!w)return U.toast('Trình duyệt đang chặn cửa sổ xem trước','err');w.document.write(reportHtml(reportRef,snap));w.document.close()}
function loadScript(src,global){if(window[global])return Promise.resolve(window[global]);return new Promise((res,rej)=>{const old=[...document.scripts].find(s=>s.src===src);if(old){old.addEventListener('load',()=>res(window[global]),{once:true});old.addEventListener('error',rej,{once:true});return}const s=document.createElement('script');s.src=src;s.onload=()=>res(window[global]);s.onerror=()=>rej(new Error('Không tải được thư viện xuất file'));document.head.appendChild(s)})}
async function exportPdf(){if(!reportRef||busy)return;busy=true;const domCount=document.querySelectorAll('#tk76-images .tk76-row').length;const snap=images.map(x=>({...x}));window.__TK76_LAST_EXPORT_DIAG={type:'pdf',domCount,stateCount:images.length,snapshotCount:snap.length,tid:reportRef?.tid||'',at:Date.now()};if(domCount>0&&snap.length===0){busy=false;U.toast('Lỗi nội bộ: ảnh đã chọn nhưng snapshot xuất đang rỗng. Không tạo PDF để tránh mất ảnh.','err');return}const st=$('tk76-status');st.textContent=`Đang tạo PDF${snap.length?` với ${snap.length} ảnh`:''}...`;try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js','html2pdf');const host=document.createElement('div');host.style.cssText='position:fixed;left:-20000px;top:0;width:1100px;background:#fff';host.innerHTML=reportHtml(reportRef,snap).match(/<body[^>]*>([\s\S]*)<\/body>/i)?.[1]||'';document.body.appendChild(host);await Promise.all([...host.querySelectorAll('img')].map(im=>im.complete?Promise.resolve():new Promise(r=>{im.onload=im.onerror=r})));await window.html2pdf().set({margin:[7,7,7,7],filename:reportFileBase(reportRef)+'.pdf',image:{type:'jpeg',quality:.92},html2canvas:{scale:1.6,useCORS:true,backgroundColor:'#ffffff'},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css','legacy']}}).from(host).save();host.remove();st.textContent='Đã xuất PDF. Ảnh tạm đã được xóa khỏi phiên tạo báo cáo.';images=[];renderImages()}catch(e){console.error(e);st.textContent='Không tạo được PDF tự động. Đang mở bản in để bạn chọn Save as PDF...';const w=window.open('','_blank');if(w){w.document.write(reportHtml(reportRef,snap));w.document.close();setTimeout(()=>w.print(),350)}}finally{busy=false}}
function addText(slide,text,x,y,w,h,opt={}){slide.addText(String(text??''),{x,y,w,h,fontFace:'Arial',fontSize:opt.size||16,bold:!!opt.bold,color:opt.color||'17324D',margin:0.04,breakLine:false,valign:opt.valign||'mid',align:opt.align||'left',fit:'shrink'})}
function imageDataWithSize(data){return new Promise(res=>{const im=new Image();im.onload=()=>res({data,w:im.width,h:im.height});im.onerror=()=>res({data,w:1600,h:900});im.src=data})}
function fit(w,h,maxW,maxH){const s=Math.min(maxW/w,maxH/h);return{w:w*s,h:h*s}}
async function addPhotoSlides(ppt,pos,sectionTitle,source=images){const arr=(source||[]).filter(x=>x.position===pos);for(let i=0;i<arr.length;i+=2){const slide=ppt.addSlide();slide.background={color:'F7FBFD'};addText(slide,sectionTitle,0.6,0.3,12.1,0.5,{size:22,bold:true,color:'0B5F80'});const pair=arr.slice(i,i+2);for(let j=0;j<pair.length;j++){const p=pair[j],meta=await imageDataWithSize(p.data),maxW=5.8,maxH=5.6,sz=fit(meta.w,meta.h,maxW,maxH),x=0.65+j*6.25+(maxW-sz.w)/2,y=1.15+(5.25-sz.h)/2;slide.addImage({data:p.data,x,y,w:sz.w,h:sz.h});if(p.hasTitle&&p.title.trim())addText(slide,p.title.trim(),0.75+j*6.25,6.48,5.6,.45,{size:13,bold:true,align:'center'})}}}
async function exportPpt(){if(!reportRef||busy)return;busy=true;const domCount=document.querySelectorAll('#tk76-images .tk76-row').length;const snap=images.map(x=>({...x}));window.__TK76_LAST_EXPORT_DIAG={type:'pptx',domCount,stateCount:images.length,snapshotCount:snap.length,tid:reportRef?.tid||'',at:Date.now()};if(domCount>0&&snap.length===0){busy=false;U.toast('Lỗi nội bộ: ảnh đã chọn nhưng snapshot xuất đang rỗng. Không tạo PowerPoint để tránh mất ảnh.','err');return}const st=$('tk76-status');st.textContent=`Đang tạo PowerPoint${snap.length?` với ${snap.length} ảnh`:''}...`;try{await loadScript('https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgen.bundle.js','PptxGenJS');const ppt=new window.PptxGenJS();ppt.layout='LAYOUT_WIDE';ppt.author='TOPKEY Sports Hub';ppt.subject='Báo cáo toàn giải';ppt.title=reportRef.title||'Báo cáo toàn giải';ppt.company='TOPKEY';ppt.lang='vi-VN';ppt.theme={headFontFace:'Arial',bodyFontFace:'Arial',lang:'vi-VN'};let s=ppt.addSlide();s.background={color:'071426'};addText(s,'BÁO CÁO TOÀN GIẢI',0.7,1.15,12,0.8,{size:30,bold:true,color:'FFFFFF'});addText(s,reportRef.title,0.7,2.1,12,0.75,{size:24,bold:true,color:'4ED3B3'});addText(s,`${reportRef.sportName} · ${fmtDate(reportRef.generatedAt)}`,0.7,3.0,12,.5,{size:16,color:'C9DDEB'});s=ppt.addSlide();addText(s,'TỔNG QUAN GIẢI',0.6,.3,12,.5,{size:24,bold:true,color:'0B5F80'});const ks=[['Đội/đối tượng',reportRef.summary?.teams||0],['Người tham gia',reportRef.summary?.participants||0],['Trận/lượt hoàn tất',`${reportRef.summary?.finished||0}/${reportRef.summary?.matches||0}`],['Nội dung',reportRef.summary?.categories||0]];ks.forEach((k,i)=>{const x=.65+(i%2)*6.25,y=1.2+Math.floor(i/2)*2.1;s.addShape(ppt.ShapeType.roundRect,{x,y,w:5.7,h:1.55,rectRadius:.08,fill:{color:'EAF5FA'},line:{color:'B8D4E2'}});addText(s,k[0],x+.25,y+.18,5.2,.35,{size:14,color:'547083'});addText(s,k[1],x+.25,y+.62,5.2,.58,{size:26,bold:true,color:'10233B'})});await addPhotoSlides(ppt,'summary','Hình ảnh · Tổng quan',snap);s=ppt.addSlide();addText(s,'THÀNH TÍCH CHUNG CUỘC',.6,.3,12,.5,{size:24,bold:true,color:'0B5F80'});let yy=1.05;for(const [cat,rows] of Object.entries(reportRef.top4||{})){addText(s,cat,.7,yy,3.4,.4,{size:16,bold:true});rows.slice(0,4).forEach((r,i)=>addText(s,`${i+1}. ${r.name}` ,4.0,yy+i*.42,8.2,.35,{size:14,bold:i===0}));yy+=Math.max(1.9,rows.length*.45+.35);if(yy>6.4){s=ppt.addSlide();yy=.7}}await addPhotoSlides(ppt,'champions','Hình ảnh · Thành tích chung cuộc',snap);for(const [cat,rows] of Object.entries(reportRef.rankings||{})){for(let off=0;off<rows.length;off+=14){s=ppt.addSlide();addText(s,`BẢNG XẾP HẠNG · ${cat}`,.6,.28,12,.5,{size:22,bold:true,color:'0B5F80'});const head=['#','Đội / VĐV','Trận','W-D-L','Điểm/Thành tích'],xs=[.6,1.25,6.2,7.25,9.15],ws=[.55,4.8,.95,1.7,3.45];head.forEach((h,i)=>addText(s,h,xs[i],.95,ws[i],.38,{size:12,bold:true,color:'FFFFFF',align:i===0?'center':'left'}));s.addShape(ppt.ShapeType.rect,{x:.55,y:.9,w:12.1,h:.48,fill:{color:'0F789D'},line:{color:'0F789D'}});rows.slice(off,off+14).forEach((r,j)=>{const y=1.48+j*.37;addText(s,r.rank,xs[0],y,ws[0],.3,{size:11,align:'center'});addText(s,r.name,xs[1],y,ws[1],.3,{size:11});addText(s,r.played??0,xs[2],y,ws[2],.3,{size:11});addText(s,S.mode==='time'||S.mode==='judged'?'—':`${r.w||0}-${r.d||0}-${r.l||0}`,xs[3],y,ws[3],.3,{size:11});addText(s,rankingValue(r),xs[4],y,ws[4],.3,{size:11})})}}await addPhotoSlides(ppt,'rankings','Hình ảnh · Bảng xếp hạng',snap);const ms=reportRef.matches||[];for(let off=0;off<ms.length;off+=12){s=ppt.addSlide();addText(s,'LỊCH & KẾT QUẢ',.6,.28,12,.5,{size:22,bold:true,color:'0B5F80'});ms.slice(off,off+12).forEach((m,j)=>{const y=1.05+j*.48;addText(s,`${off+j+1}. ${m.date} ${m.time}`,.65,y,2.2,.34,{size:10,bold:true});addText(s,`${m.teamA}${m.teamB&&m.teamB!=='—'?' vs '+m.teamB:''}`,2.95,y,5.8,.34,{size:11});addText(s,m.result,8.9,y,1.7,.34,{size:11,bold:true});addText(s,m.status,10.75,y,1.8,.34,{size:10})})}await addPhotoSlides(ppt,'results','Hình ảnh · Lịch & kết quả',snap);s=ppt.addSlide();addText(s,'TÀI CHÍNH TOÀN GIẢI',.6,.3,12,.5,{size:24,bold:true,color:'0B5F80'});addText(s,`Tổng thu: ${money(reportRef.finance?.income)}`,.8,1.25,5.5,.55,{size:20,bold:true});addText(s,`Tổng chi: ${money(reportRef.finance?.expense)}`,.8,2.0,5.5,.55,{size:20,bold:true});addText(s,`Số dư: ${money(reportRef.finance?.balance)}`,.8,2.75,5.5,.55,{size:22,bold:true,color:'0A7C5C'});addText(s,`Khoản chưa PAID: ${reportRef.finance?.pending||0}`,.8,3.5,5.5,.55,{size:16});await addPhotoSlides(ppt,'finance','Hình ảnh · Tài chính',snap);await addPhotoSlides(ppt,'final',$('tk76-final-title')?.value||'HÌNH ẢNH HOẠT ĐỘNG GIẢI',snap);await ppt.writeFile({fileName:reportFileBase(reportRef)+'.pptx'});st.textContent='Đã xuất PowerPoint. Ảnh tạm đã được xóa khỏi phiên tạo báo cáo.';images=[];renderImages()}catch(e){console.error(e);U.toast('Không tạo được PowerPoint: '+(e?.message||e),'err');st.textContent='Lỗi xuất PowerPoint: '+(e?.message||e)}finally{busy=false}}
