(()=>{
'use strict';
const T=window.Topkey,App=T?.App,U=T?.U,S=T?.SPORT;
if(!T||!App||!U||!S||!['cooking','handmade'].includes(S.key)||window.TopkeyH88Judging)return;
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={votes:{},codesShown:[],dirty:false,votesRef:null,votesHandler:null,publicStarted:false,publicCfg:null,publicTeams:{},codeHash:'',identityKey:''};
const defaultCriteria=()=>((S.rubric||[]).length?S.rubric:[{key:'skill',label:'Kỹ năng',weight:40},{key:'variety',label:'Phong phú / Sáng tạo',weight:30},{key:'aesthetic',label:'Đẹp / Trình bày',weight:30}]).map((x,i)=>({id:String(x.key||x.id||('c'+i)),label:String(x.label||('Tiêu chí '+(i+1))),weight:Number(x.weight)||0}));
const cfg=()=>{const j=App.state.config?.judging||{};return {enabled:!!j.enabled,mode:j.mode==='JUDGE_CODE'?'JUDGE_CODE':'PUBLIC_DEVICE',title:String(j.title||`Chấm điểm ${S.name}`),token:String(j.token||''),criteria:Array.isArray(j.criteria)&&j.criteria.length?j.criteria:defaultCriteria(),updatedAt:Number(j.updatedAt||0)}};
const randomToken=()=>{const a=new Uint32Array(4);crypto.getRandomValues(a);return [...a].map(x=>x.toString(36)).join('').slice(0,24)};
const randomCode=()=>{const a=new Uint32Array(1);crypto.getRandomValues(a);return String(10000000+(a[0]%90000000));};
async function sha256(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(s)));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function judgingUrl(c=cfg()){const u=new URL(location.href);u.hash='judge';u.searchParams.set('sport',S.key);u.searchParams.set('tid',T.Data.tid);u.searchParams.set('judge',c.token||'');['entry','hubTicket','__topkey_sync','recovered'].forEach(k=>u.searchParams.delete(k));return u.toString()}
function ensureCss(){if($('tk88-judge-style'))return;const s=document.createElement('style');s.id='tk88-judge-style';s.textContent=`
#tk88-judge-admin{grid-column:1/-1}.tk88j-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.tk88j-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.tk88j-criteria{display:grid;gap:8px}.tk88j-row{display:grid;grid-template-columns:minmax(180px,1fr) 120px auto;gap:8px;align-items:end;border:1px solid #28516c;padding:8px;border-radius:10px}.tk88j-row input{width:100%;box-sizing:border-box}.tk88j-total{font-weight:900}.tk88j-total.bad{color:#ff8d8d}.tk88j-total.ok{color:#60e6a7}.tk88j-qr{background:white;border-radius:12px;padding:10px;display:inline-block;min-width:180px;min-height:180px}.tk88j-link{display:flex;gap:7px}.tk88j-link input{min-width:0;flex:1}.tk88j-code-list{display:flex;gap:7px;flex-wrap:wrap;margin-top:8px}.tk88j-code{padding:7px 10px;border:1px solid #46708b;border-radius:8px;background:#081d30;font-weight:900;letter-spacing:1px}.tk88j-results{margin-top:14px}.tk88j-rank1{background:linear-gradient(90deg,#6c5110,#2b331f)!important}.tk88j-rank2{background:linear-gradient(90deg,#48515c,#24313c)!important}.tk88j-rank3{background:linear-gradient(90deg,#6c4129,#30302c)!important}.tk88j-badge{font-weight:900;font-size:18px}.tk88j-public{min-height:100vh;background:#071426;color:#eaf6ff;padding:16px}.tk88j-public>.card{max-width:760px;margin:0 auto}.tk88j-score-row{display:grid;grid-template-columns:1fr 110px;gap:10px;align-items:center;border:1px solid #294b64;border-radius:10px;padding:10px;margin:8px 0}.tk88j-score-row input{width:100%}.tk88j-public-status{padding:10px;border-radius:9px;background:#102a42;margin:10px 0}.tk88j-done{background:#123c2e;color:#8ff0bd}.tk88j-warn{background:#4b3215;color:#ffd789}.tk88j-private-note{font-size:12px;color:#9eb7c8;line-height:1.5}@media(max-width:800px){.tk88j-grid{grid-template-columns:1fr}.tk88j-row{grid-template-columns:1fr 90px auto}.tk88j-score-row{grid-template-columns:1fr 85px}}
`;document.head.appendChild(s)}
function ensurePublic(){ensureCss();if($('public-judge'))return;const sec=document.createElement('section');sec.id='public-judge';sec.className='tk88j-public hidden';sec.innerHTML=`<div class="card"><div class="split"><div><h1 id="tk88j-public-title">🎯 Chấm điểm</h1><p class="muted">${esc(S.name)} · cổng chấm điểm công khai</p></div><a class="btn" href="../../index.html">Về Hub</a></div><div id="tk88j-public-status" class="tk88j-public-status">Đang tải cấu hình...</div><div id="tk88j-code-wrap" class="field hidden"><label>Mã giám khảo do BTC cấp</label><div class="tk88j-link"><input id="tk88j-public-code" inputmode="numeric" maxlength="8" placeholder="Nhập mã 8 số"><button id="tk88j-code-login" class="btn ok" type="button">Xác nhận mã</button></div></div><form id="tk88j-public-form" class="hidden"><div class="field"><label>Đội / thí sinh</label><select id="tk88j-public-team" required></select></div><div id="tk88j-public-criteria"></div><div class="field"><label>Nhận xét (không bắt buộc)</label><textarea id="tk88j-public-note" maxlength="500"></textarea></div><div id="tk88j-public-total" class="tk88j-public-status">Tổng quy đổi: 0 / 100</div><button class="btn ok" style="width:100%" type="submit">✓ Gửi điểm</button></form><p class="tk88j-private-note" id="tk88j-public-note2"></p></div>`;document.body.appendChild(sec);$('tk88j-code-login').onclick=validateJudgeCode;$('tk88j-public-form').onsubmit=submitPublicScore;sec.addEventListener('input',updatePublicTotal)}
function criteriaRows(criteria){return criteria.map((c,i)=>`<div class="tk88j-row" data-id="${esc(c.id)}"><div class="field"><label>Tiêu chí ${i+1}</label><input class="tk88j-label" value="${esc(c.label)}" placeholder="Kỹ năng / Hương vị / Thẩm mỹ..."></div><div class="field"><label>Trọng số %</label><input class="tk88j-weight" type="number" min="1" max="100" step="1" value="${Number(c.weight)||0}"></div><button class="btn mini danger tk88j-del" type="button">Xóa</button></div>`).join('')}
function ensureAdmin(){if(!['cooking','handmade'].includes(S.key))return;ensureCss();const page=$('page-settings');if(!page||$('tk88-judge-admin'))return;const card=document.createElement('div');card.id='tk88-judge-admin';card.className='card';card.style.marginTop='14px';card.innerHTML=`<div class="tk88j-head"><div><h2 style="margin:0">🎯 Chấm điểm & QR Giám khảo</h2><p class="muted">Dùng cho ${esc(S.name)}. BTC thiết lập tiêu chí/trọng số trước khi phát QR.</p></div><div class="action-bar"><button id="tk88j-save" class="btn ok">💾 Lưu cấu hình</button><button id="tk88j-rotate" class="btn">↻ Tạo link QR mới</button></div></div><div class="tk88j-grid"><div><div class="form-grid"><div class="field"><label>Tiêu đề form chấm</label><input id="tk88j-title"></div><div class="field"><label>Chế độ truy cập</label><select id="tk88j-mode"><option value="PUBLIC_DEVICE">Công khai · 1 thiết bị = 1 phiếu toàn giải</option><option value="JUDGE_CODE">Giám khảo · mã BTC · mỗi đội 1 lần</option></select></div></div><label style="display:flex;gap:8px;align-items:center;margin:10px 0"><input id="tk88j-enabled" type="checkbox"> <b>Mở nhận chấm điểm</b></label><div class="split"><div><b>Cơ cấu tiêu chí</b><div class="muted">GK cho từng tiêu chí từ 0–10; hệ thống quy đổi theo trọng số %.</div></div><button id="tk88j-add" class="btn mini" type="button">＋ Tiêu chí</button></div><div id="tk88j-criteria" class="tk88j-criteria" style="margin-top:8px"></div><div id="tk88j-weight-total" class="tk88j-total"></div></div><div><div id="tk88j-qr" class="tk88j-qr"></div><div class="field"><label>Link chấm điểm</label><div class="tk88j-link"><input id="tk88j-link" readonly><button id="tk88j-copy" class="btn mini" type="button">⧉</button></div></div><div id="tk88j-code-admin" class="hidden"><hr><b>Mã giám khảo</b><p class="tk88j-private-note">Mã chỉ hiển thị khi vừa tạo; hệ thống lưu SHA-256, không lưu mã gốc.</p><div class="tk88j-link"><input id="tk88j-code-count" type="number" min="1" max="50" value="3"><button id="tk88j-gen-codes" class="btn mini ok" type="button">Tạo mã GK</button><button id="tk88j-clear-codes" class="btn mini danger" type="button">Xóa mã cũ</button></div><div id="tk88j-code-list" class="tk88j-code-list"></div></div><p id="tk88j-security-note" class="tk88j-private-note"></p></div></div><div class="tk88j-results"><div class="split"><div><h3 style="margin:0">📊 Thống kê chấm điểm</h3><p class="muted">Xếp hạng theo điểm trung bình quy đổi. Hạng 1/2/3 được highlight riêng.</p></div><button id="tk88j-clear-votes" class="btn mini danger" type="button">Xóa toàn bộ điểm</button></div><div class="table-wrap"><table><thead><tr id="tk88j-results-head"></tr></thead><tbody id="tk88j-results-body"></tbody></table></div></div>`;page.appendChild(card);
$('tk88j-add').onclick=()=>{const c=readCriteria();c.push({id:'c_'+Date.now().toString(36),label:'Tiêu chí mới',weight:10});renderCriteria(c);state.dirty=true};$('tk88j-save').onclick=saveConfig;$('tk88j-rotate').onclick=rotateLink;$('tk88j-copy').onclick=copyLink;$('tk88j-mode').onchange=()=>{toggleMode();state.dirty=true};$('tk88j-enabled').onchange=()=>state.dirty=true;$('tk88j-title').oninput=()=>state.dirty=true;$('tk88j-gen-codes').onclick=generateCodes;$('tk88j-clear-codes').onclick=clearCodes;$('tk88j-clear-votes').onclick=clearVotes;renderAdminFromConfig(true);listenVotes()}
function renderCriteria(c){const box=$('tk88j-criteria');if(!box)return;box.innerHTML=criteriaRows(c);box.querySelectorAll('input').forEach(x=>x.oninput=()=>{state.dirty=true;updateWeightTotal()});box.querySelectorAll('.tk88j-del').forEach(b=>b.onclick=()=>{b.closest('.tk88j-row')?.remove();state.dirty=true;updateWeightTotal()});updateWeightTotal()}
function readCriteria(){return [...($('tk88j-criteria')?.querySelectorAll('.tk88j-row')||[])].map((r,i)=>({id:String(r.dataset.id||('c'+i)),label:String(r.querySelector('.tk88j-label')?.value||'').trim(),weight:Number(r.querySelector('.tk88j-weight')?.value)||0})).filter(x=>x.label&&x.weight>0)}
function updateWeightTotal(){const n=readCriteria().reduce((s,x)=>s+x.weight,0),el=$('tk88j-weight-total');if(el){el.textContent=`Tổng trọng số: ${n}% ${n===100?'✓':'· cần đúng 100% trước khi phát QR'}`;el.className='tk88j-total '+(n===100?'ok':'bad')}return n}
function renderAdminFromConfig(force=false){if(!$('tk88-judge-admin')||state.dirty&&!force)return;const c=cfg();$('tk88j-title').value=c.title;$('tk88j-mode').value=c.mode;$('tk88j-enabled').checked=c.enabled;renderCriteria(c.criteria);renderQr(c);toggleMode();renderResults();state.dirty=false}
function toggleMode(){const m=$('tk88j-mode')?.value||cfg().mode;$('tk88j-code-admin')?.classList.toggle('hidden',m!=='JUDGE_CODE');const note=$('tk88j-security-note');if(note)note.textContent=m==='PUBLIC_DEVICE'?'Chế độ công khai: server khóa create-only theo Device ID. Xóa dữ liệu trình duyệt/đổi trình duyệt có thể tạo ID mới, vì vậy dùng mã GK nếu cần kiểm soát chặt.':'Chế độ mã GK: mỗi mã có thể chấm mỗi đội đúng 1 lần; mã hợp lệ được kiểm tra trực tiếp bằng Firebase Rules.'}
function renderQr(c=cfg()){const link=judgingUrl(c);if($('tk88j-link'))$('tk88j-link').value=link;const q=$('tk88j-qr');if(!q)return;q.innerHTML='';if(!c.token||updateWeightTotal()!==100){q.innerHTML='<div style="color:#333;padding:25px 8px;text-align:center">Lưu cấu hình đủ 100% để tạo QR</div>';return}try{new QRCode(q,{text:link,width:180,height:180})}catch(e){q.textContent=link}}
async function copyLink(){try{await navigator.clipboard.writeText($('tk88j-link').value);U.toast('Đã sao chép link chấm điểm','ok')}catch{}}
async function saveConfig(){const criteria=readCriteria(),sum=criteria.reduce((s,x)=>s+x.weight,0);if(sum!==100)return U.toast('Tổng trọng số phải đúng 100%','err');let old=cfg();const out={enabled:$('tk88j-enabled').checked,mode:$('tk88j-mode').value,title:$('tk88j-title').value.trim()||`Chấm điểm ${S.name}`,token:old.token||randomToken(),criteria,updatedAt:Date.now(),updatedBy:T.Auth?.user?.uid||''};try{await T.Data.queueSet('config/judging',out,{type:'JUDGING_CONFIG'});App.state.config=App.state.config||{};App.state.config.judging=out;state.dirty=false;renderAdminFromConfig(true);window.TopkeyUpgrade14?.render?.();U.toast('Đã lưu cấu hình chấm điểm','ok')}catch(e){U.toast('Không lưu được cấu hình chấm điểm: '+(e?.message||e),'err')}}
async function rotateLink(){const criteria=readCriteria();if(criteria.reduce((s,x)=>s+x.weight,0)!==100)return U.toast('Tổng trọng số phải đúng 100%','err');if(!confirm('Tạo link QR mới? Link cũ sẽ không còn gửi điểm được.'))return;const old=cfg(),out={...old,token:randomToken(),criteria,enabled:$('tk88j-enabled').checked,mode:$('tk88j-mode').value,title:$('tk88j-title').value.trim()||old.title,updatedAt:Date.now(),updatedBy:T.Auth?.user?.uid||''};await T.Data.queueSet('config/judging',out,{type:'JUDGING_ROTATE_TOKEN'});App.state.config.judging=out;state.dirty=false;renderAdminFromConfig(true);window.TopkeyUpgrade14?.render?.();U.toast('Đã tạo link/QR mới','ok')}
async function generateCodes(){if(($('tk88j-mode')?.value||'')!=='JUDGE_CODE')return;const n=Math.max(1,Math.min(50,Number($('tk88j-code-count').value)||1)),plain=[],updates={};try{for(let i=0;i<n;i++){let code='',h='',exists=true,tries=0;while(exists&&tries++<12){code=randomCode();if(plain.includes(code))continue;h=await sha256(code);exists=(await T.Data.db.ref(T.Data.path('judgeAccessCodes/'+h)).once('value')).exists()}if(!code||exists)throw new Error('Không tạo được mã GK duy nhất');plain.push(code);updates[`${T.Data.path('judgeAccessCodes')}/${h}`]={active:true,createdAt:Date.now(),createdBy:T.Auth?.user?.uid||'',label:`GK ${i+1}`}}await T.Data.db.ref().update(updates);state.codesShown=plain;renderCodes();U.toast(`Đã tạo ${n} mã giám khảo. Hãy lưu lại ngay.`, 'ok')}catch(e){U.toast('Không tạo được mã GK: '+(e?.message||e),'err')}}
function renderCodes(){const b=$('tk88j-code-list');if(!b)return;b.innerHTML=state.codesShown.length?state.codesShown.map((c,i)=>`<span class="tk88j-code">GK${i+1}: ${c}</span>`).join(''):'<span class="muted">Chưa tạo mã mới trong phiên này.</span>'}
async function clearCodes(){if(!confirm('Xóa toàn bộ mã GK hiện tại? Các mã đã phát sẽ hết hiệu lực.'))return;try{await T.Data.db.ref(T.Data.path('judgeAccessCodes')).remove();state.codesShown=[];renderCodes();U.toast('Đã vô hiệu toàn bộ mã GK','ok')}catch(e){U.toast(e.message,'err')}}
async function clearVotes(){if(!confirm('Xóa toàn bộ dữ liệu chấm điểm của giải này?'))return;try{await T.Data.db.ref(T.Data.path('judgingVotes')).remove();U.toast('Đã xóa dữ liệu chấm điểm','ok')}catch(e){U.toast(e.message,'err')}}
function flattenVotes(){const out=[],v=state.votes||{};Object.values(v.public||{}).forEach(x=>x&&out.push(x));Object.values(v.judges||{}).forEach(byTeam=>Object.values(byTeam||{}).forEach(x=>x&&out.push(x)));return out}
function renderResults(){const head=$('tk88j-results-head'),body=$('tk88j-results-body');if(!head||!body)return;const c=cfg(),criteria=c.criteria||[],teams=App.state.teams||{},votes=flattenVotes(),agg={};Object.values(teams).forEach(t=>agg[t.id]={id:t.id,name:t.name||t.code||t.id,n:0,total:0,criteria:Object.fromEntries(criteria.map(x=>[x.id,0]))});votes.forEach(v=>{const a=agg[v.teamId];if(!a)return;a.n++;a.total+=Number(v.total)||0;criteria.forEach(x=>a.criteria[x.id]+=Number(v.scores?.[x.id])||0)});const rows=Object.values(agg).map(a=>({...a,avg:a.n?a.total/a.n:0})).sort((a,b)=>b.avg-a.avg||b.n-a.n||a.name.localeCompare(b.name,'vi'));head.innerHTML=`<th>Hạng</th><th>Đội / thí sinh</th><th>Lượt chấm</th>${criteria.map(x=>`<th>${esc(x.label)}<br><small>${x.weight}%</small></th>`).join('')}<th>Điểm TB /100</th>`;body.innerHTML=rows.map((r,i)=>`<tr class="${i===0?'tk88j-rank1':i===1?'tk88j-rank2':i===2?'tk88j-rank3':''}"><td class="tk88j-badge">${i+1}${i===0?' 🥇':i===1?' 🥈':i===2?' 🥉':''}</td><td><b>${esc(r.name)}</b></td><td>${r.n}</td>${criteria.map(x=>`<td>${r.n?(r.criteria[x.id]/r.n).toFixed(2):'—'}</td>`).join('')}<td><b>${r.n?r.avg.toFixed(2):'—'}</b></td></tr>`).join('')}
function listenVotes(){if(!T.Data?.db||state.votesRef)return;try{state.votesRef=T.Data.db.ref(T.Data.path('judgingVotes'));state.votesHandler=s=>{state.votes=s.val()||{};renderResults()};state.votesRef.on('value',state.votesHandler)}catch(e){console.warn('H88 judging vote listener',e)}}
function stopVotes(){try{state.votesRef?.off('value',state.votesHandler)}catch{}state.votesRef=state.votesHandler=null}
async function deviceHash(token){let id=localStorage.getItem('topkey_public_device_v1');if(!id){id=crypto.randomUUID?crypto.randomUUID():randomToken()+randomToken();localStorage.setItem('topkey_public_device_v1',id)}return sha256(`${T.Data.tid}|${S.key}|${token}|${id}`)}
async function startPublic(){if(location.hash!=='#judge'||state.publicStarted)return;state.publicStarted=true;ensurePublic();$('login-screen')?.classList.add('hidden');$('app-shell')?.classList.add('hidden');$('public-spectator')?.classList.add('hidden');$('public-register')?.classList.add('hidden');$('public-judge')?.classList.remove('hidden');try{const token=new URLSearchParams(location.search).get('judge')||'',base=T.Data.path(),[cs,ts]=await Promise.all([T.Data.db.ref(base+'/config').once('value'),T.Data.db.ref(base+'/teams').once('value')]);App.state.config=cs.val()||{};App.state.teams=ts.val()||{};const c=cfg();state.publicCfg=c;state.publicTeams=App.state.teams||{};$('tk88j-public-title').textContent='🎯 '+c.title;const invalid=!c.enabled||!c.token||token!==c.token||!c.criteria?.length||c.criteria.reduce((s,x)=>s+Number(x.weight||0),0)!==100;if(invalid){$('tk88j-public-status').textContent='Link chấm điểm không hợp lệ, đã thay thế hoặc đang tạm đóng.';return}if(c.mode==='JUDGE_CODE'){$('tk88j-code-wrap').classList.remove('hidden');$('tk88j-public-status').textContent='Nhập mã giám khảo do BTC cấp để bắt đầu chấm.';$('tk88j-public-note2').textContent='Mỗi mã giám khảo được chấm mỗi đội đúng 1 lần.'}else{state.identityKey=await deviceHash(c.token);const key=`topkey_judge_done_${T.Data.tid}_${state.identityKey}`;let done=[];try{done=JSON.parse(localStorage.getItem(key)||'[]')}catch{};$('tk88j-public-status').textContent=done.includes('__ALL__')?'Thiết bị/trình duyệt này đã gửi phiếu cho giải này.':'Chế độ công khai: thiết bị/trình duyệt này được gửi 1 phiếu toàn giải.';$('tk88j-public-note2').textContent='Phiếu được khóa theo ID trình duyệt/thiết bị và Firebase create-only. Đổi trình duyệt hoặc xóa dữ liệu trình duyệt có thể tạo ID mới; BTC nên dùng chế độ mã GK cho chấm chính thức.';showPublicForm();if(done.includes('__ALL__')){$('tk88j-public-form').querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=true);$('tk88j-public-status').className='tk88j-public-status tk88j-done'}}}catch(e){console.error('H88 public judging',e);$('tk88j-public-status').textContent='Không tải được form chấm điểm: '+(e?.message||e)}}
function showPublicForm(){const c=state.publicCfg||cfg(),teams=Object.values(state.publicTeams||{}).filter(t=>!t.withdrawn);$('tk88j-public-team').innerHTML='<option value="">-- Chọn đội / thí sinh --</option>'+teams.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'vi')).map(t=>`<option value="${esc(t.id)}">${esc(t.name||t.code||t.id)}</option>`).join('');$('tk88j-public-criteria').innerHTML=c.criteria.map(x=>`<div class="tk88j-score-row" data-id="${esc(x.id)}" data-weight="${Number(x.weight)||0}"><div><b>${esc(x.label)}</b><div class="muted">Trọng số ${Number(x.weight)||0}% · cho điểm 0–10</div><input class="tk88j-score-range" type="range" min="0" max="10" step="0.1" value="0"></div><input class="tk88j-score-number" type="number" min="0" max="10" step="0.1" value="0"></div>`).join('');$('tk88j-public-criteria').querySelectorAll('.tk88j-score-row').forEach(r=>{const range=r.querySelector('.tk88j-score-range'),num=r.querySelector('.tk88j-score-number');range.oninput=()=>{num.value=range.value;updatePublicTotal()};num.oninput=()=>{let v=Math.max(0,Math.min(10,Number(num.value)||0));num.value=v;range.value=v;updatePublicTotal()}});$('tk88j-public-form').classList.remove('hidden');updatePublicTotal()}
async function validateJudgeCode(){const code=String($('tk88j-public-code').value||'').replace(/\D/g,'');if(code.length!==8)return $('tk88j-public-status').textContent='Mã GK phải gồm 8 chữ số.';try{const h=await sha256(code),s=await T.Data.db.ref(T.Data.path('judgeAccessCodes/'+h)).once('value');if(!s.val()?.active)return $('tk88j-public-status').textContent='Mã giám khảo không hợp lệ hoặc đã bị BTC thu hồi.';state.codeHash=h;state.identityKey=h;$('tk88j-public-status').textContent='Mã hợp lệ. Bạn có thể chấm từng đội; mỗi đội chỉ ghi nhận 1 lần.';$('tk88j-code-wrap').classList.add('hidden');showPublicForm();const key=`topkey_judge_done_${T.Data.tid}_${state.identityKey}`;let done=[];try{done=JSON.parse(localStorage.getItem(key)||'[]')}catch{};for(const teamId of done){const o=[...$('tk88j-public-team').options].find(x=>x.value===teamId);if(o){o.disabled=true;if(!o.textContent.includes('✓'))o.textContent+=' ✓ đã chấm'}}}catch(e){$('tk88j-public-status').textContent='Không xác thực được mã GK: '+(e?.message||e)}}
function collectScores(){const scores={};let total=0;[...$('tk88j-public-criteria').querySelectorAll('.tk88j-score-row')].forEach(r=>{const v=Math.max(0,Math.min(10,Number(r.querySelector('.tk88j-score-number').value)||0)),w=Number(r.dataset.weight)||0;scores[r.dataset.id]=v;total+=(v/10)*w});return{scores,total:Math.round(total*100)/100}}
function updatePublicTotal(){if(!$('tk88j-public-total'))return;const x=collectScores();$('tk88j-public-total').textContent=`Tổng quy đổi: ${x.total.toFixed(2)} / 100`}
async function submitPublicScore(e){e.preventDefault();const c=state.publicCfg||cfg(),teamId=$('tk88j-public-team').value;if(!teamId)return $('tk88j-public-status').textContent='Vui lòng chọn đội / thí sinh.';const {scores,total}=collectScores(),note=String($('tk88j-public-note').value||'').trim().slice(0,500),now=Date.now(),token=new URLSearchParams(location.search).get('judge')||'';try{let path,row;if(c.mode==='PUBLIC_DEVICE'){if(!state.identityKey)state.identityKey=await deviceHash(c.token);path=T.Data.path('judgingVotes/public/'+state.identityKey);row={teamId,scores,total,note,createdAt:now,identityType:'PUBLIC_DEVICE',token}}else{if(!state.codeHash)return $('tk88j-public-status').textContent='Cần xác thực mã giám khảo.';path=T.Data.path(`judgingVotes/judges/${state.codeHash}/${teamId}`);row={teamId,scores,total,note,createdAt:now,identityType:'JUDGE_CODE',codeHash:state.codeHash}}await T.Data.db.ref(path).set(row);$('tk88j-public-status').className='tk88j-public-status tk88j-done';$('tk88j-public-status').textContent=c.mode==='PUBLIC_DEVICE'?'Đã ghi nhận phiếu của thiết bị này. Cảm ơn bạn!':'Đã lưu điểm đội này. Bạn có thể chọn đội khác để tiếp tục chấm.';const key=`topkey_judge_done_${T.Data.tid}_${state.identityKey}`;let done=[];try{done=JSON.parse(localStorage.getItem(key)||'[]')}catch{};if(c.mode==='PUBLIC_DEVICE'){localStorage.setItem(key,JSON.stringify(['__ALL__']));$('tk88j-public-form').querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=true)}else{if(!done.includes(teamId))done.push(teamId);localStorage.setItem(key,JSON.stringify(done));const o=[...$('tk88j-public-team').options].find(x=>x.value===teamId);if(o){o.disabled=true;o.textContent+=' ✓ đã chấm'}$('tk88j-public-team').value='';$('tk88j-public-criteria').querySelectorAll('input').forEach(x=>x.value=0);$('tk88j-public-note').value='';updatePublicTotal()}}catch(err){const msg=String(err?.message||err);$('tk88j-public-status').className='tk88j-public-status tk88j-warn';$('tk88j-public-status').textContent=/permission|denied/i.test(msg)?(c.mode==='PUBLIC_DEVICE'?'Thiết bị này đã bình chọn hoặc link đã hết hiệu lực.':'Đội này đã được chấm bằng mã GK này, hoặc mã đã hết hiệu lực.'):'Không gửi được điểm: '+msg}}
function patchPublicHash(){const old=App.handlePublicHash?.bind(App);if(App.__tk88JudgeHash)return;App.__tk88JudgeHash=true;App.handlePublicHash=function(){old?.();const j=location.hash==='#judge';$('login-screen')?.classList.toggle('hidden',j||location.hash==='#spectator'||location.hash==='#register');$('public-judge')?.classList.toggle('hidden',!j);if(j)setTimeout(startPublic,0)}}
function patchAfterLogin(){if(App.__tk88JudgeAfter)return;App.__tk88JudgeAfter=true;const old=App.afterLogin?.bind(App);App.afterLogin=async function(...a){const r=await old?.(...a);ensureAdmin();renderAdminFromConfig(true);listenVotes();return r};const oldConfig=App.renderConfig?.bind(App);if(oldConfig)App.renderConfig=function(...a){const r=oldConfig(...a);ensureAdmin();renderAdminFromConfig(false);return r};const oldTeams=App.renderTeams?.bind(App);if(oldTeams)App.renderTeams=function(...a){const r=oldTeams(...a);renderResults();return r}}
ensurePublic();patchPublicHash();patchAfterLogin();if(document.readyState!=='loading'){ensureAdmin();if(location.hash==='#judge')setTimeout(startPublic,0)}else document.addEventListener('DOMContentLoaded',()=>{ensureAdmin();if(location.hash==='#judge')setTimeout(startPublic,0)},{once:true});
window.addEventListener('hashchange',()=>{state.publicStarted=false;if(location.hash==='#judge')setTimeout(startPublic,0)});
window.TopkeyH88Judging={cfg,judgingUrl,sha256,startPublic,renderResults,readCriteria,collectScores};
})();

;

